-- 0309: the audit-log retention sweep keeps the stored-daily-totals rebuild record forever (lane/sales-daily-totals).
--
-- lib/audit.ts AUDIT_RETENTION_KEPT_ENTITY_ACTIONS gained system/sales_daily_rebuild: clearing a quarantine the nightly check raised is an owner-mandated action, kept like
-- reset_data, factory_reset and a backup restore. The partial index idx_audit_logs_retention_deletable is built from the same predicate text (AUDIT_RETENTION_DELETABLE_SQL,
-- whitespace collapsed); without this rebuild the planner would fall back to idx_audit_logs_created (cost only, never a wrong delete: the delete keeps its own full predicate).
--
-- PRE:  idx_audit_logs_retention_deletable exists (0303). Index rebuild only: no row of any table changes.
-- POST: the index exists again on audit_logs(created_at) with the new predicate (it names sales_daily_rebuild). Asserted at the end.
-- RECOVERY: schema only. DROP INDEX idx_audit_logs_retention_deletable; then recreate it with the 0303 predicate (without sales_daily_rebuild).
DROP INDEX idx_audit_logs_retention_deletable;

CREATE INDEX idx_audit_logs_retention_deletable ON audit_logs (created_at) WHERE NOT (LOWER(TRIM(COALESCE(NULLIF(TRIM(entity), ''), table_name, ''))) IN ('sale', 'sale_creation', 'sale_item', 'sales', 'payment_method', 'customer_receivables', 'supplier_invoices', 'return', 'returns', 'return_create', 'return_reason', 'supplier_return', 'stock', 'stock_transfer', 'stock_transfers', 'stock_session', 'stock_session_operations', 'inventory', 'inventory_movements', 'inventory_reason', 'product_batch', 'product_batches', 'branch_stock_integrity', 'branch_cutover', 'role', 'roles', 'fee', 'fee_label', 'fee_type', 'shift_session', 'read_switch') OR (LOWER(TRIM(COALESCE(NULLIF(TRIM(entity), ''), table_name, ''))) = 'user' AND COALESCE(action, '') IN ('create', 'update')) OR (LOWER(TRIM(COALESCE(NULLIF(TRIM(entity), ''), table_name, ''))) = 'users' AND COALESCE(action, '') IN ('create', 'update')) OR (LOWER(TRIM(COALESCE(NULLIF(TRIM(entity), ''), table_name, ''))) = 'product' AND COALESCE(action, '') IN ('create', 'update', 'cost_override', 'catalog_cost_recompute_backfill')) OR (LOWER(TRIM(COALESCE(NULLIF(TRIM(entity), ''), table_name, ''))) = 'products' AND COALESCE(action, '') IN ('create', 'update', 'cost_override', 'catalog_cost_recompute_backfill')) OR (LOWER(TRIM(COALESCE(NULLIF(TRIM(entity), ''), table_name, ''))) = 'system' AND COALESCE(action, '') IN ('reset_data', 'factory_reset', 'finalize_migration', 'sales_daily_rebuild')) OR (LOWER(TRIM(COALESCE(NULLIF(TRIM(entity), ''), table_name, ''))) = 'data-integrity' AND COALESCE(action, '') IN ('repair')) OR (LOWER(TRIM(COALESCE(NULLIF(TRIM(entity), ''), table_name, ''))) = 'backup' AND COALESCE(action, '') IN ('restore')) OR (LOWER(TRIM(COALESCE(NULLIF(TRIM(entity), ''), table_name, ''))) = 'import_job' AND COALESCE(action, '') IN ('import_job_approve', 'import_job_retry')) OR (LOWER(TRIM(COALESCE(NULLIF(TRIM(entity), ''), table_name, ''))) = 'customer' AND COALESCE(action, '') IN ('merge', 'link_sales', 'relink_sales', 'create_and_link_sales', 'customer_same_name_phone_merge', 'mark_anonymous_customer', 'clear_shared_general_membership')) OR (LOWER(TRIM(COALESCE(NULLIF(TRIM(entity), ''), table_name, ''))) = 'supplier' AND COALESCE(action, '') IN ('merge', 'supplier_duplicate_cluster_merge')) OR (LOWER(TRIM(COALESCE(NULLIF(TRIM(entity), ''), table_name, ''))) = 'delivery_contact' AND COALESCE(action, '') IN ('merge')) OR (LOWER(TRIM(COALESCE(NULLIF(TRIM(entity), ''), table_name, ''))) = '' AND COALESCE(action, '') IN ('sale', 'sale_settlement', 'return')) OR COALESCE(action, '') IN ('stock_add', 'stock_remove', 'stock_set', 'stock_adjust', 'stock_in_line_edit', 'stock_movement_reason_edit', 'stock_tagged_dispose', 'stock_tagged_restore', 'transfer', 'transfer_intent', 'merge_duplicate', 'fold', 'product_same_name_merge', 'product_transfer_aware_merge', 'product_leading_zero_twin_merge', 'received_date_saleability_repair', 'stale_receipt_revert_mirror', 'recompute_stock_cache', 'branch_cutover_inactive_stock', 'branch_cutover_approved_fold', 'branch_cutover_inactive_fold', 'branch_cutover_lot_fold', 'branch_cutover_completed', 'undo_closed_branch_cutover', 'stock_revert', 'stock_revert_repair', 'stock_revert_repair_before') OR (LOWER(TRIM(COALESCE(NULLIF(TRIM(entity), ''), table_name, ''))) IN ('product', 'products', 'action_history', '') AND (COALESCE(action, '') LIKE '%\_undo' ESCAPE '\' OR COALESCE(action, '') LIKE '%\_redo' ESCAPE '\'))) AND NOT (COALESCE(entity, '') = 'pending_action' AND (COALESCE(CASE WHEN json_valid(details) THEN json_extract(details, '$.section') END, '') IN ('fees') OR (COALESCE(action, '') = 'approve' AND COALESCE(CASE WHEN json_valid(details) THEN json_extract(details, '$.section') END, '') IN ('products', 'inventory', 'returns', 'contacts'))));

SELECT CASE WHEN (SELECT COUNT(*) FROM sqlite_master WHERE type = 'index' AND name = 'idx_audit_logs_retention_deletable' AND tbl_name = 'audit_logs' AND sql LIKE '%sales_daily_rebuild%') = 1
THEN 1 ELSE json_extract('[]','$[audit_retention_0309_post]') END;
